/* Synthetic guard-syntax check for the CVE-2017-16914 port.
 * Mirrors the field types used by the added guard but is NOT a kernel build.
 */
#include <stddef.h>

struct device { int dummy; };
struct usb_device { struct device dev; };
struct urb {
	unsigned int actual_length;
	void *transfer_buffer;
	unsigned int pipe;
};

struct stub_device {
	struct usb_device *udev;
};

#define dev_err(dev, fmt, ...) ((void)0)
#define usb_pipein(pipe) ((pipe) & 0x80)

static int guard_check(struct stub_device *sdev, struct urb *urb)
{
	/* --- exact guard text inserted by the candidate (minus leading tabs) --- */
	if (urb->actual_length > 0 && !urb->transfer_buffer) {
		dev_err(&sdev->udev->dev,
			"urb: actual_length %d transfer_buffer null\n",
			urb->actual_length);
		return -1;
	}
	/* --- end guard text --- */
	return (int)urb->actual_length;
}

int main(void)
{
	struct usb_device u;
	struct stub_device s = { &u };
	struct urb a = { 0, (void *)0, 0 };
	struct urb b = { 16, (void *)0x1000, 0 };
	return guard_check(&s, &a) + guard_check(&s, &b);
}

